  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
  WebhookId,
} from "./common";
import type { Role } from "./member";
import type { ProjectVisibility } from "./project";

/**
 * The complete action vocabulary of `can()`. Every authorization decision in
 * Taskflow names one of these — there is no free-form string permission.
 */
export type PermissionAction =
  | "org:read"
  | "org:update"
  | "org:delete"
  | "org:manage_billing"
  | "org:manage_flags"
  | "member:read"
  | "member:invite"
  | "member:update_role"
  | "member:remove"
  | "project:create"
  | "project:read"
  | "project:update"
  | "project:archive"
  | "project:delete"
  | "issue:create"
  | "issue:read"
  | "issue:update"
  | "issue:assign"
  | "issue:archive"
  | "issue:delete"
  | "comment:create"
  | "comment:read"
  | "comment:update"
  | "comment:delete"
  | "activity:read"
  | "activity:export"
  | "notification:read"
  | "notification:manage"
  | "webhook:manage";

/**
 * The object a permission is asked about. Discriminated on `kind` so the
 * ownership rules inside `can()` can read the fields they need without casts.
 */
export type PermissionResource =
  | { readonly kind: "organization"; readonly orgId: OrgId }
  | { readonly kind: "billing"; readonly orgId: OrgId }
  | {
      readonly kind: "member";
      readonly orgId: OrgId;
      readonly memberId: MemberId;
      readonly targetUserId: UserId;
      readonly targetRole: Role;
    }
  | {
      readonly kind: "project";
      readonly orgId: OrgId;
      readonly projectId: ProjectId;
      readonly visibility: ProjectVisibility;
      readonly leadId: UserId | null;
    }
  | {
      readonly kind: "issue";
      readonly orgId: OrgId;
      readonly projectId: ProjectId;
      readonly issueId: IssueId;
      readonly authorId: UserId;
      readonly assigneeId: UserId | null;
    }
  | {
      readonly kind: "comment";
      readonly orgId: OrgId;
      readonly commentId: CommentId;
      readonly authorId: UserId;
    }
  | { readonly kind: "activity"; readonly orgId: OrgId }
  | { readonly kind: "notification"; readonly orgId: OrgId; readonly recipientId: UserId }
  | { readonly kind: "webhook"; readonly orgId: OrgId; readonly webhookId: WebhookId | null };

export type PermissionResourceKind = PermissionResource["kind"];

/** Verbose form of a decision, used by the settings UI to explain a denial. */
export interface PermissionDecision {
  readonly allowed: boolean;
  readonly action: PermissionAction;
  readonly resourceKind: PermissionResourceKind;
  readonly reason:
    | "granted_by_role"
    | "granted_by_ownership"
    | "granted_by_staff"
    | "denied_by_role"
    | "denied_cross_tenant"
    | "denied_unknown_action";
}
/**
 * Exhaustive role×action sweep of `ROLE_MATRIX`, including ownership
 * escalations and the cross-tenant denial.
 */
import { describe, expect, it } from "vitest";
import { ROLE_MATRIX, can, canAll, explain } from "@/lib/permissions";
import type { IssueId, ProjectId } from "@/types/common";
import { ROLES, ROLE_RANK, type Role } from "@/types/member";
import type { PermissionAction, PermissionResource } from "@/types/permission";
import { ALICE, BOB, ORG_A, ORG_B, makeActor } from "../helpers/factories";

const ACTIONS = Object.keys(ROLE_MATRIX) as readonly PermissionAction[];

/**
 * A resource in ORG_A owned by nobody the actor is, so the sweep measures the
 * matrix alone and never trips an ownership escalation.
 */
const foreignOwned: PermissionResource = {
  kind: "issue",
  orgId: ORG_A,
  projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
  issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
  authorId: BOB,
  assigneeId: BOB,
};

const orgResource: PermissionResource = { kind: "organization", orgId: ORG_A };

describe("permissions matrix", () => {
  it("covers every declared action", () => {
    expect(ACTIONS.length).toBeGreaterThan(20);
    for (const action of ACTIONS) {
      expect(ROLES).toContain(ROLE_MATRIX[action]);
    }
  });

  it("grants exactly the roles at or above the required rank", () => {
    for (const action of ACTIONS) {
      const required = ROLE_MATRIX[action];
      for (const role of ROLES) {
        const expected = ROLE_RANK[role] >= ROLE_RANK[required];
        expect(
          can(makeActor({ role, userId: ALICE }), action, foreignOwned),
          `${role} → ${action}`,
        ).toBe(expected);
      }
    }
  });

  it("reports `granted_by_role` and `denied_by_role` as the reason", () => {
    expect(explain(makeActor({ role: "owner" }), "org:delete", orgResource).reason).toBe(
      "granted_by_role",
    );
    expect(explain(makeActor({ role: "admin" }), "org:delete", orgResource).reason).toBe(
      "denied_by_role",
    );
  });

  it("denies every action across a tenant boundary, whatever the role", () => {
    for (const role of ROLES) {
      const foreign = makeActor({ role, orgId: ORG_B });
      for (const action of ACTIONS) {
        expect(can(foreign, action, orgResource), `${role} → ${action}`).toBe(false);
      }
    }
    expect(explain(makeActor({ orgId: ORG_B }), "org:read", orgResource).reason).toBe(
      "denied_cross_tenant",
    );
  });

  it("checks the tenant boundary before the staff bypass", () => {
    const staff = makeActor({ orgId: ORG_B, isPlatformStaff: true, role: "owner" });
    expect(can(staff, "org:read", orgResource)).toBe(false);
    expect(explain(staff, "org:read", orgResource).reason).toBe("denied_cross_tenant");
  });

  it("lets platform staff bypass the matrix inside their own tenant", () => {
    const staff = makeActor({ role: "viewer", isPlatformStaff: true });
    for (const action of ACTIONS) {
      expect(can(staff, action, orgResource), action).toBe(true);
    }
    expect(explain(staff, "org:delete", orgResource).reason).toBe("granted_by_staff");
  });

  it("puts billing and deletion behind the owner role alone", () => {
    for (const action of ["org:delete", "org:manage_billing", "project:delete"] as const) {
      expect(ROLE_MATRIX[action]).toBe("owner");
      expect(can(makeActor({ role: "admin" }), action, orgResource)).toBe(false);
      expect(can(makeActor({ role: "owner" }), action, orgResource)).toBe(true);
    }
  });

  it("keeps the everyday read actions available to a viewer", () => {
    for (const action of [
      "org:read",
      "member:read",
      "project:read",
      "issue:read",
      "comment:read",
      "notification:read",
    ] as const) {
      expect(ROLE_MATRIX[action], action).toBe("viewer");
      expect(can(makeActor({ role: "viewer" }), action, orgResource), action).toBe(true);
    }
  });

  it("holds the audit trail above viewer, unlike the other reads", () => {
    expect(ROLE_MATRIX["activity:read"]).toBe("member");
    expect(can(makeActor({ role: "viewer" }), "activity:read", orgResource)).toBe(false);
    expect(can(makeActor({ role: "member" }), "activity:read", orgResource)).toBe(true);
  });

  it("requires every listed action to pass in the bulk form", () => {
    const admin = makeActor({ role: "admin" });
    expect(canAll(admin, ["member:read", "member:invite"], orgResource)).toBe(true);
    expect(canAll(admin, ["member:invite", "org:delete"], orgResource)).toBe(false);
    expect(canAll(makeActor({ role: "viewer" }), [], orgResource)).toBe(true);
  });

  it("reports `denied_unknown_action` for an action outside the vocabulary", () => {
    const decision = explain(
      makeActor({ role: "owner" }),
      "issue:teleport" as PermissionAction,
      orgResource,
    );
    expect(decision.allowed).toBe(false);
    expect(decision.reason).toBe("denied_unknown_action");
  });

  it("names the resource kind that was asked about", () => {
    const roles: readonly Role[] = ["owner", "viewer"];
    for (const role of roles) {
      expect(explain(makeActor({ role }), "org:read", orgResource).resourceKind).toBe(
        "organization",
      );
      expect(explain(makeActor({ role }), "issue:read", foreignOwned).resourceKind).toBe(
        "issue",
      );
    }
  });
});
import { describe, expect, it } from "vitest";
import { can, explain, assertCan, PermissionDeniedError, ROLE_MATRIX } from "@/lib/permissions";
import type { Actor, Role } from "@/types/member";
import type { OrgId, UserId, IssueId, ProjectId, CommentId } from "@/types/common";
import type { PermissionAction, PermissionResource } from "@/types/permission";
import {
  commentIdSchema,
  issueIdSchema,
  orgIdSchema,
  projectIdSchema,
  userIdSchema,
} from "@/schemas/common";

const ORG = "01HZZZGGGGGGGGGGGGGGGGGGGG" as OrgId;
const OTHER_ORG = "01HZZZHHHHHHHHHHHHHHHHHHHH" as OrgId;
const ALICE = "01HZZZAAAAAAAAAAAAAAAAAAAA" as UserId;
const BOB = "01HZZZBBBBBBBBBBBBBBBBBBBB" as UserId;

function actor(role: Role, overrides: Partial<Actor> = {}): Actor {
  return { userId: ALICE, orgId: ORG, role, ...overrides };
}

const orgResource: PermissionResource = { kind: "organization", orgId: ORG };

function issueBy(authorId: UserId, assigneeId: UserId | null = null): PermissionResource {
  return {
    kind: "issue",
    orgId: ORG,
    projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
    authorId,
    assigneeId,
  };
}

function commentBy(authorId: UserId): PermissionResource {
  return {
    kind: "comment",
    orgId: ORG,
    commentId: "01HZZZCCCCCCCCCCCCCCCCCCCC" as CommentId,
    authorId,
  };
}

describe("can()", () => {
  it("grants an action when the actor's role meets the matrix requirement", () => {
    expect(can(actor("owner"), "org:delete", orgResource)).toBe(true);
    expect(can(actor("admin"), "member:invite", { kind: "organization", orgId: ORG })).toBe(true);
    expect(can(actor("viewer"), "issue:read", issueBy(BOB))).toBe(true);
  });

  it("denies an action below the actor's role rank", () => {
    expect(can(actor("admin"), "org:delete", orgResource)).toBe(false);
    expect(can(actor("member"), "member:invite", orgResource)).toBe(false);
    expect(can(actor("viewer"), "issue:create", issueBy(ALICE))).toBe(false);
  });

  it("denies every action across a tenant boundary, even for an owner", () => {
    const foreign = actor("owner", { orgId: OTHER_ORG });
    for (const action of Object.keys(ROLE_MATRIX) as PermissionAction[]) {
      expect(can(foreign, action, orgResource)).toBe(false);
    }
    expect(explain(foreign, "org:read", orgResource).reason).toBe("denied_cross_tenant");
  });

  it("escalates for ownership: an author may edit their own issue and comment", () => {
    const viewer = actor("viewer");
    expect(can(viewer, "issue:update", issueBy(ALICE))).toBe(true);
    expect(can(viewer, "issue:update", issueBy(BOB))).toBe(false);
    expect(can(viewer, "comment:update", commentBy(ALICE))).toBe(true);
    expect(can(viewer, "comment:delete", commentBy(BOB))).toBe(false);
    expect(explain(viewer, "issue:update", issueBy(ALICE)).reason).toBe(
      "granted_by_ownership",
    );
  });

  it("does not escalate ownership for actions outside the escalation list", () => {
    expect(can(actor("viewer"), "issue:delete", issueBy(ALICE))).toBe(false);
  });

  it("lets platform staff bypass the matrix inside the tenant", () => {
    const staff = actor("viewer", { isPlatformStaff: true });
    expect(can(staff, "org:delete", orgResource)).toBe(true);
    expect(explain(staff, "org:delete", orgResource).reason).toBe("granted_by_staff");
  });

  it("assertCan throws PermissionDeniedError on a denial", () => {
    expect(() => assertCan(actor("viewer"), "org:delete", orgResource)).toThrow(
      PermissionDeniedError,
    );
    expect(() => assertCan(actor("owner"), "org:delete", orgResource)).not.toThrow();
  });

  it("keeps the matrix monotonic: a higher role never loses an action", () => {
    const ranks: Role[] = ["viewer", "member", "admin", "owner"];
    for (const action of Object.keys(ROLE_MATRIX) as PermissionAction[]) {
      let seenAllowed = false;
      for (const role of ranks) {
        const allowed = can(actor(role), action, orgResource);
        if (seenAllowed) expect(allowed).toBe(true);
        if (allowed) seenAllowed = true;
      }
    }
  });
});

describe("fixture ids", () => {
  // The ids above are cast with `as`, which skips validation. If a fixture
  // drifts outside Crockford base32 (no I, L, O, U) the permission tests keep
  // passing while every schema in `src/schemas` would reject the same value —
  // so the contract fixtures are checked against the real schema here.
  it("are valid ULIDs under the shared branded-id schemas", () => {
    expect(orgIdSchema.parse(ORG)).toBe(ORG);
    expect(orgIdSchema.parse(OTHER_ORG)).toBe(OTHER_ORG);
    expect(userIdSchema.parse(ALICE)).toBe(ALICE);
