const MS_PER_DAY = 24 * 60 * 60 * 1000;
const TOKEN_RANDOM_BYTES = 32;

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write" && !hasRoleAtLeast(actor.role, "member")) {
    assertCan(
      { ...actor, isPlatformStaff: false },
      "project:create",
      orgResource(parsed.orgId),
    );
  }

  const createdAt = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(
    new Date(Date.parse(createdAt) + parsed.expiresInDays * MS_PER_DAY),
  );
  const token = `tfk_${randomToken(TOKEN_RANDOM_BYTES)}`;
  const apiToken = await apiTokenRepo.insertApiToken({
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    tokenHash: hashToken(token),
    prefix: token.slice(0, 12),
    expiresAt,
    createdAt,
  });

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    apiTokenId: apiToken.id,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    assertCan(
      { ...actor, isPlatformStaff: false },
      "member:update_role",
      orgResource(orgId),
    );
  }
  return apiTokenRepo.listApiTokens(orgId, userId);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);
  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "API token",
    tokenId,
  );

  if (existing.userId !== actor.userId) {
    assertCan(
      { ...actor, isPlatformStaff: false },
      "member:update_role",
      orgResource(orgId),
    );
  }

  const result = requireFound(
    await apiTokenRepo.revokeApiToken(
      orgId,
      tokenId,
      toIsoTimestamp(new Date()),
    ),
    "API token",
    tokenId,
  );

  if (result.changed) {
    await emit("api_token.revoked", {
      ...actorEnvelope(actor),
      apiTokenId: result.apiToken.id,
    });
  }
  return result.apiToken;
}

export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const now = toIsoTimestamp(new Date());
  const found = await apiTokenRepo.findUsableApiToken(hashToken(token), now);
  if (!found) return null;

  const touched = await apiTokenRepo.touchApiToken(
    found.apiToken.orgId,
    found.apiToken.id,
    now,
  );
  if (!touched) return null;

  return {
    userId: found.apiToken.userId,
    orgId: found.apiToken.orgId,
    role: found.apiToken.scope === "read" ? "viewer" : found.role,
  };
}

/** Revokes and audits every unrevoked token after a member removal event. */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const revokedAt = toIsoTimestamp(new Date());
    const tokens = await apiTokenRepo.revokeTokensForMemberRemoval(
      payload.orgId,
      payload.userId,
      revokedAt,
    );

    await Promise.all(
      tokens.map((apiToken) =>
        emit("api_token.revoked", {
          orgId: payload.orgId,
          actorId: payload.actorId,
          occurredAt: revokedAt,
          apiTokenId: apiToken.id,
        }),
      ),
    );
  });
}
/** Hashed API-token persistence. The secret hash never leaves this repository. */
import { and, count, desc, eq, gt, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, apiTokens, members, organizations } from "@/server/db";
import { toApiToken } from "./_mappers";
import type { ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Role } from "@/types/member";
import type { ApiToken } from "@/types/api-token";

export async function insertApiToken(input: {
  orgId: OrgId;
  userId: UserId;
  name: string;
  scope: ApiTokenScope;
  tokenHash: string;
  prefix: string;
  expiresAt: IsoTimestamp;
  createdAt: IsoTimestamp;
}): Promise<ApiToken> {
  const db = getDb();
  return db.transaction((tx) => {
    const existing = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(
        and(
          eq(apiTokens.orgId, input.orgId),
          eq(apiTokens.userId, input.userId),
          isNull(apiTokens.revokedAt),
          gt(apiTokens.expiresAt, input.createdAt),
        ),
      )
      .get();

    if ((existing?.value ?? 0) >= 5) {
      throw new Error("A user may hold at most 5 usable API tokens per organization");
    }

    const row = tx
      .insert(apiTokens)
      .values({
        id: newId(),
        orgId: input.orgId,
        userId: input.userId,
        name: input.name,
        scope: input.scope,
        tokenHash: input.tokenHash,
        prefix: input.prefix,
        expiresAt: input.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: input.createdAt,
      })
      .returning()
      .get();

    return toApiToken(row);
  });
}

export async function listApiTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(and(eq(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)))
    .orderBy(desc(apiTokens.createdAt), desc(apiTokens.id))
    .all();
  return rows.map(toApiToken);
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(eq(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

export async function revokeApiToken(
  orgId: OrgId,
  tokenId: string,
  revokedAt: IsoTimestamp,
): Promise<{ apiToken: ApiToken; changed: boolean } | null> {
  const db = getDb();
  const updated = db
    .update(apiTokens)
    .set({ revokedAt })
    .where(
      and(
        eq(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  if (updated) return { apiToken: toApiToken(updated), changed: true };

  const current = db
    .select()
    .from(apiTokens)
    .where(and(eq(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return current ? { apiToken: toApiToken(current), changed: false } : null;
}

/** Revokes every unrevoked token, including expired ones, for a removed user. */
export async function revokeTokensForMemberRemoval(
  orgId: OrgId,
  userId: UserId,
  revokedAt: IsoTimestamp,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .update(apiTokens)
    .set({ revokedAt })
    .where(
      and(
        eq(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .all();
  return rows.map(toApiToken);
}

export async function findUsableApiToken(
  tokenHash: string,
  now: IsoTimestamp,
): Promise<{ apiToken: ApiToken; role: Role } | null> {
  const row = getDb()
    .select({ apiToken: apiTokens, role: members.role })
    .from(apiTokens)
    .innerJoin(
      members,
      and(
        eq(members.orgId, apiTokens.orgId),
        eq(members.userId, apiTokens.userId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .innerJoin(
      organizations,
      and(eq(organizations.id, apiTokens.orgId), isNull(organizations.archivedAt)),
    )
    .where(
      and(
        eq(apiTokens.tokenHash, tokenHash),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, now),
      ),
    )
    .get();

  return row ? { apiToken: toApiToken(row.apiToken), role: row.role } : null;
}

export async function touchApiToken(
  orgId: OrgId,
  tokenId: string,
  now: IsoTimestamp,
): Promise<boolean> {
  const row = getDb()
    .update(apiTokens)
    .set({ lastUsedAt: now })
    .where(
      and(
        eq(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, now),
      ),
    )
    .returning({ id: apiTokens.id })
    .get();
  return row !== undefined;
}
